BEGIN TRANSACTION;
CREATE TABLE academic_classes (
	id INTEGER NOT NULL, 
	class_code VARCHAR(50) NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	programme_id INTEGER, 
	batch_name VARCHAR(50) NOT NULL, 
	semester_num INTEGER, 
	section_name VARCHAR(10), 
	tutor_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(programme_id) REFERENCES programmes (id), 
	FOREIGN KEY(tutor_id) REFERENCES faculty (id)
);
CREATE TABLE academic_years (
	id INTEGER NOT NULL, 
	year_code VARCHAR(20) NOT NULL, 
	is_current BOOLEAN, 
	PRIMARY KEY (id), 
	UNIQUE (year_code)
);
CREATE TABLE approval_history (
	id INTEGER NOT NULL, 
	workflow_id INTEGER, 
	action VARCHAR(50) NOT NULL, 
	comments TEXT, 
	acted_by_id INTEGER, 
	timestamp DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(workflow_id) REFERENCES approval_workflows (id), 
	FOREIGN KEY(acted_by_id) REFERENCES users (id)
);
CREATE TABLE approval_workflows (
	id INTEGER NOT NULL, 
	entity_type VARCHAR(50) NOT NULL, 
	entity_id INTEGER NOT NULL, 
	current_status VARCHAR(30), 
	submitted_by_id INTEGER, 
	reviewer_id INTEGER, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(submitted_by_id) REFERENCES users (id), 
	FOREIGN KEY(reviewer_id) REFERENCES users (id)
);
CREATE TABLE assessment_attempts (
	id INTEGER NOT NULL, 
	assessment_id INTEGER, 
	student_id INTEGER, 
	start_time DATETIME, 
	submit_time DATETIME, 
	status VARCHAR(20), 
	total_score FLOAT, 
	malpractice_flagged BOOLEAN, 
	tab_switch_count INTEGER, 
	violation_logs JSON, 
	webcam_enabled BOOLEAN, 
	webcam_snapshots JSON, 
	PRIMARY KEY (id), 
	FOREIGN KEY(assessment_id) REFERENCES assessments (id), 
	FOREIGN KEY(student_id) REFERENCES students (id)
);
CREATE TABLE assessments (
	id INTEGER NOT NULL, 
	title VARCHAR(150) NOT NULL, 
	assessment_type VARCHAR(50), 
	course_id INTEGER, 
	max_marks FLOAT, 
	weightage_percent FLOAT, 
	start_time DATETIME, 
	end_time DATETIME, 
	duration_minutes INTEGER, 
	instructions TEXT, 
	is_online BOOLEAN, 
	status VARCHAR(30), 
	question_paper_id INTEGER, 
	created_by_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id), 
	FOREIGN KEY(question_paper_id) REFERENCES question_papers (id), 
	FOREIGN KEY(created_by_id) REFERENCES users (id)
);
CREATE TABLE assignment_submissions (
	id INTEGER NOT NULL, 
	assignment_id INTEGER, 
	student_id INTEGER, 
	submission_text TEXT, 
	file_path VARCHAR(255), 
	submitted_at DATETIME, 
	is_late BOOLEAN, 
	marks_awarded FLOAT, 
	feedback TEXT, 
	rubric_evaluation JSON, 
	status VARCHAR(30), 
	PRIMARY KEY (id), 
	FOREIGN KEY(assignment_id) REFERENCES assignments (id), 
	FOREIGN KEY(student_id) REFERENCES students (id)
);
CREATE TABLE assignments (
	id INTEGER NOT NULL, 
	title VARCHAR(150) NOT NULL, 
	description TEXT, 
	course_id INTEGER, 
	max_marks FLOAT, 
	due_date DATETIME NOT NULL, 
	allow_late_submission BOOLEAN, 
	rubric_id INTEGER, 
	created_by_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id), 
	FOREIGN KEY(rubric_id) REFERENCES rubrics (id), 
	FOREIGN KEY(created_by_id) REFERENCES users (id)
);
CREATE TABLE audit_logs (
	id INTEGER NOT NULL, 
	user_id INTEGER, 
	action VARCHAR(100) NOT NULL, 
	module VARCHAR(50) NOT NULL, 
	record_id VARCHAR(50), 
	old_value TEXT, 
	new_value TEXT, 
	ip_address VARCHAR(50), 
	timestamp DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE batches (
	id INTEGER NOT NULL, 
	name VARCHAR(50) NOT NULL, 
	start_year INTEGER NOT NULL, 
	end_year INTEGER NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE co_po_mappings (
	id INTEGER NOT NULL, 
	co_id INTEGER, 
	po_id INTEGER, 
	weightage INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(co_id) REFERENCES course_outcomes (id), 
	FOREIGN KEY(po_id) REFERENCES programme_outcomes (id)
);
CREATE TABLE co_pso_mappings (
	id INTEGER NOT NULL, 
	co_id INTEGER, 
	pso_id INTEGER, 
	weightage INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(co_id) REFERENCES course_outcomes (id), 
	FOREIGN KEY(pso_id) REFERENCES programme_specific_outcomes (id)
);
CREATE TABLE course_allocations (
	id INTEGER NOT NULL, 
	faculty_id INTEGER, 
	course_id INTEGER, 
	academic_year VARCHAR(20), 
	semester_num INTEGER, 
	section_name VARCHAR(10), 
	batch_name VARCHAR(50), 
	PRIMARY KEY (id), 
	FOREIGN KEY(faculty_id) REFERENCES faculty (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);
CREATE TABLE course_enrolments (
	id INTEGER NOT NULL, 
	student_id INTEGER, 
	course_id INTEGER, 
	academic_year VARCHAR(20), 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);
CREATE TABLE course_outcomes (
	id INTEGER NOT NULL, 
	code VARCHAR(20) NOT NULL, 
	statement TEXT NOT NULL, 
	bloom_level VARCHAR(30), 
	course_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);
CREATE TABLE courses (
	id INTEGER NOT NULL, 
	code VARCHAR(30) NOT NULL, 
	title VARCHAR(150) NOT NULL, 
	course_type VARCHAR(50), 
	credits FLOAT, 
	semester_num INTEGER, 
	regulation VARCHAR(20), 
	programme_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(programme_id) REFERENCES programmes (id)
);
CREATE TABLE departments (
	id INTEGER NOT NULL, 
	code VARCHAR(20) NOT NULL, 
	name VARCHAR(150) NOT NULL, 
	school_id INTEGER, hod_id INTEGER REFERENCES faculty(id), 
	PRIMARY KEY (id), 
	UNIQUE (code), 
	FOREIGN KEY(school_id) REFERENCES schools (id)
);
CREATE TABLE faculty (
	id INTEGER NOT NULL, 
	user_id INTEGER, 
	employee_id VARCHAR(30) NOT NULL, 
	designation VARCHAR(100), 
	department_id INTEGER, 
	status VARCHAR(20), 
	assigned_programme_id INTEGER, 
	assigned_batch VARCHAR(50), 
	assigned_section VARCHAR(10), 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(department_id) REFERENCES departments (id), 
	FOREIGN KEY(assigned_programme_id) REFERENCES programmes (id)
);
CREATE TABLE learning_resources (
	id INTEGER NOT NULL, 
	title VARCHAR(150) NOT NULL, 
	filename VARCHAR(255) NOT NULL, 
	course_id INTEGER NOT NULL, 
	unit INTEGER, 
	topic VARCHAR(150), 
	chunks_count INTEGER, 
	vectors_count INTEGER, 
	file_size_bytes INTEGER, 
	uploaded_by_id INTEGER, 
	created_at DATETIME, 
	status VARCHAR(50), 
	PRIMARY KEY (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id), 
	FOREIGN KEY(uploaded_by_id) REFERENCES users (id)
);
CREATE TABLE marks (
	id INTEGER NOT NULL, 
	student_id INTEGER, 
	course_id INTEGER, 
	assessment_id INTEGER, 
	marks_obtained FLOAT, 
	is_absent BOOLEAN, 
	is_exempted BOOLEAN, 
	remarks VARCHAR(255), 
	status VARCHAR(20), 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id), 
	FOREIGN KEY(assessment_id) REFERENCES assessments (id)
);
CREATE TABLE notifications (
	id INTEGER NOT NULL, 
	user_id INTEGER, 
	title VARCHAR(150) NOT NULL, 
	message TEXT NOT NULL, 
	type VARCHAR(30), 
	is_read BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);
CREATE TABLE programme_outcomes (
	id INTEGER NOT NULL, 
	code VARCHAR(20) NOT NULL, 
	statement TEXT NOT NULL, 
	programme_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(programme_id) REFERENCES programmes (id)
);
CREATE TABLE programme_specific_outcomes (
	id INTEGER NOT NULL, 
	code VARCHAR(20) NOT NULL, 
	statement TEXT NOT NULL, 
	programme_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(programme_id) REFERENCES programmes (id)
);
CREATE TABLE programmes (
	id INTEGER NOT NULL, 
	code VARCHAR(20) NOT NULL, 
	name VARCHAR(150) NOT NULL, 
	degree_type VARCHAR(50), 
	department_id INTEGER, 
	duration_years INTEGER, 
	PRIMARY KEY (id), 
	UNIQUE (code), 
	FOREIGN KEY(department_id) REFERENCES departments (id)
);
CREATE TABLE question_options (
	id INTEGER NOT NULL, 
	question_id INTEGER, 
	option_text TEXT NOT NULL, 
	is_correct BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(question_id) REFERENCES questions (id) ON DELETE CASCADE
);
CREATE TABLE question_paper_questions (
	id INTEGER NOT NULL, 
	paper_id INTEGER, 
	question_id INTEGER, 
	section_name VARCHAR(20), 
	order_num INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(paper_id) REFERENCES question_papers (id) ON DELETE CASCADE, 
	FOREIGN KEY(question_id) REFERENCES questions (id)
);
CREATE TABLE question_papers (
	id INTEGER NOT NULL, 
	title VARCHAR(150) NOT NULL, 
	course_id INTEGER, 
	academic_year VARCHAR(20), 
	max_marks FLOAT, 
	duration_minutes INTEGER, 
	created_by_id INTEGER, 
	status VARCHAR(30), 
	blueprint_metadata JSON, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id), 
	FOREIGN KEY(created_by_id) REFERENCES users (id)
);
CREATE TABLE questions (
	id INTEGER NOT NULL, 
	question_text TEXT NOT NULL, 
	course_id INTEGER, 
	unit INTEGER, 
	topic VARCHAR(100), 
	marks FLOAT, 
	difficulty VARCHAR(20), 
	bloom_level VARCHAR(30), 
	question_type VARCHAR(30), 
	co_id INTEGER, 
	solution_answer TEXT, 
	keywords VARCHAR(255), 
	created_by_id INTEGER, 
	created_at DATETIME, 
	status VARCHAR(20), 
	PRIMARY KEY (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id), 
	FOREIGN KEY(co_id) REFERENCES course_outcomes (id), 
	FOREIGN KEY(created_by_id) REFERENCES users (id)
);
CREATE TABLE results (
	id INTEGER NOT NULL, 
	student_id INTEGER, 
	course_id INTEGER, 
	academic_year VARCHAR(20), 
	semester_num INTEGER, 
	cia_score FLOAT, 
	cia_max FLOAT, 
	percentage FLOAT, 
	status VARCHAR(20), 
	is_published BOOLEAN, 
	published_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(student_id) REFERENCES students (id), 
	FOREIGN KEY(course_id) REFERENCES courses (id)
);
CREATE TABLE roles (
	id INTEGER NOT NULL, 
	name VARCHAR(50) NOT NULL, 
	description VARCHAR(255), 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE roster_approval_batches (
	id INTEGER NOT NULL, 
	tutor_id INTEGER NOT NULL, 
	programme_id INTEGER NOT NULL, 
	section_name VARCHAR(10), 
	batch_name VARCHAR(50), 
	semester_num INTEGER, 
	file_name VARCHAR(255), 
	status VARCHAR(30), 
	staged_data JSON NOT NULL, 
	rejection_notes TEXT, 
	created_at DATETIME, 
	approved_at DATETIME, 
	approved_by_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tutor_id) REFERENCES users (id), 
	FOREIGN KEY(programme_id) REFERENCES programmes (id), 
	FOREIGN KEY(approved_by_id) REFERENCES users (id)
);
CREATE TABLE rubric_criteria (
	id INTEGER NOT NULL, 
	rubric_id INTEGER, 
	criterion_name VARCHAR(100) NOT NULL, 
	max_marks FLOAT, 
	weightage FLOAT, 
	co_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(rubric_id) REFERENCES rubrics (id) ON DELETE CASCADE, 
	FOREIGN KEY(co_id) REFERENCES course_outcomes (id)
);
CREATE TABLE rubric_levels (
	id INTEGER NOT NULL, 
	criteria_id INTEGER, 
	level_name VARCHAR(50) NOT NULL, 
	description TEXT, 
	marks FLOAT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(criteria_id) REFERENCES rubric_criteria (id) ON DELETE CASCADE
);
CREATE TABLE rubrics (
	id INTEGER NOT NULL, 
	title VARCHAR(150) NOT NULL, 
	description TEXT, 
	created_by_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(created_by_id) REFERENCES users (id)
);
CREATE TABLE schools (
	id INTEGER NOT NULL, 
	code VARCHAR(20) NOT NULL, 
	name VARCHAR(150) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (code)
);
CREATE TABLE sections (
	id INTEGER NOT NULL, 
	name VARCHAR(10) NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE semesters (
	id INTEGER NOT NULL, 
	number INTEGER NOT NULL, 
	name VARCHAR(50) NOT NULL, 
	academic_year VARCHAR(20) NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE student_answers (
	id INTEGER NOT NULL, 
	attempt_id INTEGER, 
	question_id INTEGER, 
	selected_option_id INTEGER, 
	descriptive_text TEXT, 
	marks_awarded FLOAT, 
	evaluator_feedback TEXT, 
	is_marked_for_review BOOLEAN, 
	PRIMARY KEY (id), 
	FOREIGN KEY(attempt_id) REFERENCES assessment_attempts (id) ON DELETE CASCADE, 
	FOREIGN KEY(question_id) REFERENCES questions (id), 
	FOREIGN KEY(selected_option_id) REFERENCES question_options (id)
);
CREATE TABLE students (
	id INTEGER NOT NULL, 
	user_id INTEGER, 
	register_number VARCHAR(30) NOT NULL, 
	programme_id INTEGER, 
	batch_name VARCHAR(50) NOT NULL, 
	semester_num INTEGER, 
	section_name VARCHAR(10), 
	initial_password VARCHAR(100), 
	status VARCHAR(20), 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(programme_id) REFERENCES programmes (id)
);
CREATE TABLE user_roles (
	user_id INTEGER NOT NULL, 
	role_id INTEGER NOT NULL, 
	PRIMARY KEY (user_id, role_id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(role_id) REFERENCES roles (id) ON DELETE CASCADE
);
CREATE TABLE users (
	id INTEGER NOT NULL, 
	username VARCHAR(50) NOT NULL, 
	email VARCHAR(100) NOT NULL, 
	hashed_password VARCHAR(255) NOT NULL, 
	full_name VARCHAR(100) NOT NULL, 
	mobile VARCHAR(20), 
	is_active BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (email)
);
CREATE INDEX ix_roles_id ON roles (id);
CREATE INDEX ix_users_id ON users (id);
CREATE UNIQUE INDEX ix_users_username ON users (username);
CREATE INDEX ix_schools_id ON schools (id);
CREATE INDEX ix_academic_years_id ON academic_years (id);
CREATE INDEX ix_semesters_id ON semesters (id);
CREATE INDEX ix_batches_id ON batches (id);
CREATE INDEX ix_sections_id ON sections (id);
CREATE INDEX ix_departments_id ON departments (id);
CREATE INDEX ix_rubrics_id ON rubrics (id);
CREATE INDEX ix_notifications_id ON notifications (id);
CREATE INDEX ix_approval_workflows_id ON approval_workflows (id);
CREATE INDEX ix_audit_logs_id ON audit_logs (id);
CREATE INDEX ix_programmes_id ON programmes (id);
CREATE INDEX ix_approval_history_id ON approval_history (id);
CREATE INDEX ix_students_id ON students (id);
CREATE UNIQUE INDEX ix_students_register_number ON students (register_number);
CREATE UNIQUE INDEX ix_faculty_employee_id ON faculty (employee_id);
CREATE INDEX ix_faculty_id ON faculty (id);
CREATE UNIQUE INDEX ix_courses_code ON courses (code);
CREATE INDEX ix_courses_id ON courses (id);
CREATE INDEX ix_programme_outcomes_id ON programme_outcomes (id);
CREATE INDEX ix_programme_specific_outcomes_id ON programme_specific_outcomes (id);
CREATE INDEX ix_roster_approval_batches_id ON roster_approval_batches (id);
CREATE INDEX ix_course_allocations_id ON course_allocations (id);
CREATE INDEX ix_course_enrolments_id ON course_enrolments (id);
CREATE INDEX ix_course_outcomes_id ON course_outcomes (id);
CREATE INDEX ix_question_papers_id ON question_papers (id);
CREATE INDEX ix_assignments_id ON assignments (id);
CREATE INDEX ix_results_id ON results (id);
CREATE INDEX ix_co_po_mappings_id ON co_po_mappings (id);
CREATE INDEX ix_co_pso_mappings_id ON co_pso_mappings (id);
CREATE INDEX ix_questions_id ON questions (id);
CREATE INDEX ix_assessments_id ON assessments (id);
CREATE INDEX ix_assignment_submissions_id ON assignment_submissions (id);
CREATE INDEX ix_rubric_criteria_id ON rubric_criteria (id);
CREATE INDEX ix_question_options_id ON question_options (id);
CREATE INDEX ix_question_paper_questions_id ON question_paper_questions (id);
CREATE INDEX ix_assessment_attempts_id ON assessment_attempts (id);
CREATE INDEX ix_rubric_levels_id ON rubric_levels (id);
CREATE INDEX ix_marks_id ON marks (id);
CREATE INDEX ix_student_answers_id ON student_answers (id);
CREATE INDEX ix_academic_classes_id ON academic_classes (id);
CREATE UNIQUE INDEX ix_academic_classes_class_code ON academic_classes (class_code);
CREATE INDEX ix_learning_resources_id ON learning_resources (id);
COMMIT;
